.itn{max-width:1040px;margin:auto;color:#392f3c;font:16px/1.95 'Yu Gothic',Meiryo,sans-serif;line-break:strict;word-break:auto-phrase;background:linear-gradient(145deg,#faf5f7,#f5f1fa 65%,#fcf8f4);border-radius:18px;overflow:hidden}.itn *{box-sizing:border-box}.itn .itn-hero{padding:clamp(20px,5vw,70px);background:#e9dbea url("https://ishidahihuka.jp/wp-content/uploads/2026/11/ishida-aventurine-toning.webp") center/cover no-repeat}.itn .itn-glass,.itn section{border:1px solid #fff;background:rgba(255,255,255,.76);border-radius:16px;box-shadow:0 7px 26px #60426012}.itn .itn-glass{backdrop-filter:blur(5px);max-width:650px;padding:clamp(20px,5vw,52px)}.itn h2,.itn h3,.itn dt,.itn nav a,.itn .itn-btn,.itn summary{font-family:'Yu Mincho','Hiragino Mincho ProN',serif;color:#463345}.itn h2{font-size:clamp(24px,3.1vw,36px);line-height:1.5;margin:0 0 .65em;border:0;padding:0}.itn .itn-glass h2{font-size:clamp(32px,5vw,58px);margin:.35em 0;letter-spacing:.025em}.itn h3{font-size:21px;margin:1.3em 0 .3em}.itn p{margin:.7em 0 1em}.itn section,.itn nav{margin:clamp(12px,3vw,32px)}.itn section{padding:clamp(18px,4vw,40px);scroll-margin-top:90px}.itn nav{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.itn nav a,.itn .itn-btn{display:inline-block;padding:10px 14px;text-align:center;background:linear-gradient(160deg,#fffcf5,#e8dfcf);border:1px solid #b99a63;border-radius:9px;color:#493a36;text-decoration:none;box-shadow:0 3px 10px #67523c18}.itn nav a:hover,.itn .itn-btn:hover{background:#e6dced}.itn dt{font-weight:bold;font-size:20px}.itn dt small{font-size:14px;color:#725c70}.itn dd{margin:0 0 1em;padding:.2em 0 1em;border-bottom:1px solid #dfd4df}.itn .itn-table{overflow-x:auto}.itn table{border-collapse:collapse;min-width:490px;width:100%;font-variant-numeric:tabular-nums}.itn table th,.itn table td{padding:10px 8px;text-align:right;white-space:nowrap;border:1px solid #e4dce2}.itn table th:first-child{text-align:left}.itn thead{background:#eee6ef}.itn ol{padding-left:1.55em}.itn li{margin-bottom:.7em}.itn details{border-bottom:1px solid #ddd0dc;padding:.85em 0}.itn summary{cursor:pointer;font-weight:bold}.itn .itn-scroll{display:none}@media(max-width:680px){.itn nav{grid-template-columns:repeat(2,1fr)}.itn .itn-scroll{display:block}.itn section{padding:18px}.itn nav a{padding:10px 4px}}
.itn .itn-hero{padding:clamp(22px,5vw,60px);background-position:65% 50%}.itn .itn-glass{background:rgba(255,252,254,.83);width:min(63%,640px);max-width:none;padding:clamp(24px,4vw,46px)}.itn #itn-area dt{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.itn .itn-ink{display:inline-block;flex:none;height:44px;background-image:url('https://ishidahihuka.jp/wp-content/uploads/2026/11/ishida-toning-handwritten.png');background-size:156px 220px;background-repeat:no-repeat;font-size:0}.itn .itn-ink-1{width:122px;background-position:0 0}.itn .itn-ink-2{width:84px;background-position:0 -44px}.itn .itn-ink-3{width:156px;background-position:0 -88px}.itn .itn-ink-4{width:84px;background-position:0 -132px}.itn .itn-ink-5{width:122px;background-position:0 -176px}.itn #itn-area dt small{font-weight:400}.itn .itn-btn{font-weight:bold;padding:12px 26px}.itn .itn-btn::after{content:'　›'}.itn .itn-btn:hover{background:#e6dced}@media(max-width:680px){.itn .itn-hero{padding:42px 15px 28px;background-position:78% center}.itn .itn-glass{width:100%;padding:20px 15px}.itn .itn-glass h2{font-size:clamp(25px,6.9vw,37px)}}body.postid-2501 #main_col{background:transparent}.itn.itn-pastel{overflow:visible;border-radius:0;background:transparent}.itn-pastel .itn-hero{position:relative;display:grid;grid-template-columns:minmax(0,1.65fr) minmax(180px,1fr);align-items:center;gap:clamp(18px,3vw,44px);padding:clamp(24px,4vw,54px);border:1px solid #ffffffd9;border-radius:24px;box-shadow:0 10px 38px #73567616;overflow:hidden}.itn-pastel .itn-glass{position:relative;width:auto;padding:clamp(18px,3vw,32px);background:rgba(255,252,255,.72);border:1px solid white;backdrop-filter:blur(7px)}.itn-pastel .itn-glass h2{font-size:clamp(32px,4vw,52px);line-height:1.32;margin:.32em 0}.itn-pastel .itn-glass p{line-height:1.75}.itn-pastel .itn-facts{align-self:end;position:relative;margin:0;padding:12px 18px;background:#fff9ffbf;border:1px solid #fff;border-radius:14px;backdrop-filter:blur(5px)}.itn-pastel .itn-facts div{padding:7px 0}.itn-pastel .itn-facts div+div{border-top:1px solid #d5c4d3}.itn-pastel .itn-facts dt{font:500 13px/1.5 sans-serif;color:#6d5169}.itn-pastel .itn-facts dd{font:600 18px/1.55 'Yu Mincho',serif;margin:0;padding:0;border:0}.itn-pastel nav,.itn-pastel section{margin:clamp(16px,2.5vw,28px) 0}.itn-pastel section{background:linear-gradient(115deg,rgba(255,249,251,.88),rgba(249,244,255,.82));border:1px solid #fff;border-radius:18px;backdrop-filter:blur(6px);box-shadow:0 5px 22px #6a456419}.itn-pastel section h2{font-size:clamp(24px,2.6vw,34px);line-height:1.45}.itn-pastel .itn-pattern,.itn-pastel .itn-sites{display:grid;gap:14px;margin:16px 0 0}.itn-pastel .itn-pattern{grid-template-columns:repeat(3,minmax(0,1fr))}.itn-pastel .itn-sites{grid-template-columns:repeat(2,minmax(0,1fr))}.itn-pastel .itn-pattern>div,.itn-pastel .itn-sites>div{padding:16px 20px;border-radius:12px;border:1px solid #dbcddd;background:linear-gradient(145deg,#fff9fdde,#efebf9cc)}.itn-pastel .itn-pattern>div:nth-child(2n),.itn-pastel .itn-sites>div:nth-child(2n){background:linear-gradient(145deg,#fff9fcdb,#f6e7eacc)}.itn-pastel .itn-pattern h3{margin:0 0 7px}.itn-pastel .itn-pattern p,.itn-pastel .itn-sites dd{margin:0;padding:0;border:0}.itn-pastel .itn-sites dt{margin:0 0 8px}.itn-pastel .itn-glints{pointer-events:none;position:absolute;inset:0}.itn-pastel .itn-glints:before,.itn-pastel .itn-glints:after,.itn-pastel section.itn-wave:after{content:'';position:absolute;pointer-events:none;width:13px;height:15px;top:12%;right:14%;background:#fffdf4;clip-path:polygon(50% 0,58% 39%,100% 50%,60% 57%,50% 100%,43% 60%,0 50%,41% 43%)}.itn-pastel .itn-glints:after{width:7px;height:8px;right:13%;top:11%}.itn-pastel section.itn-wave{position:relative}.itn-pastel section.itn-wave:after{background:#cdb69e;right:18px;top:14px;width:9px;height:12px}@media(max-width:700px){.itn-pastel .itn-hero{grid-template-columns:minmax(0,1fr);gap:12px;padding:24px 12px 14px}.itn-pastel .itn-glass{padding:17px 14px}.itn-pastel .itn-glass h2{font-size:clamp(25px,6.7vw,38px)}.itn-pastel .itn-facts{padding:8px 14px}.itn-pastel .itn-facts div{display:flex;flex-wrap:wrap;gap:4px 12px;align-items:baseline;padding:3px 0}.itn-pastel .itn-facts dd{font-size:15px}.itn-pastel .itn-sites,.itn-pastel .itn-pattern{grid-template-columns:1fr;gap:9px}.itn-pastel .itn-pattern>div,.itn-pastel .itn-sites>div{padding:13px}.itn-pastel .itn-glints:before{top:8px}.itn-pastel .itn-glints:after{top:5px}}body.postid-2501 #container{background:#f4edf5 url('https://ishidahihuka.jp/wp-content/uploads/2026/11/ishida-toning-stone-original.jpg') center / 100% auto scroll repeat-y}body.postid-2501 #main_contents,body.postid-2501 #main_col,.itn.itn-pastel .itn-hero{background:transparent}.itn-pastel p:empty{display:none}.itn-pastel .itn-glass{grid-column:1}.itn-pastel .itn-facts{grid-column:2}@media(max-width:700px){.itn-pastel .itn-facts{grid-column:1}}
.itn-glints,.itn-pastel section.itn-wave:after{display:none}
body.postid-2501 #container{background:#fcfafb}.itn.itn-pastel .itn-hero{background:#f3eaf3 url('https://ishidahihuka.jp/wp-content/uploads/2026/11/ishida-toning-blank-stone.jpg') center / cover no-repeat}.itn.itn-pastel,.itn.itn-pastel :is(p,strong,small,dt,dd,h2,h3,li,summary,th,td,a){color:#000}.itn-pastel .itn-sites dt strong{font:600 23px/1.5 'Yu Mincho','Hiragino Mincho ProN',serif}
.itn.itn-pastel :is(nav a,.itn-btn,summary):not(:hover):not(:focus-visible){background:#f2dce9;color:#000}.itn.itn-pastel :is(nav a,.itn-btn,summary):is(:hover,:focus-visible){background:#e6dced;color:#000}.itn.itn-pastel section p a:not(.itn-btn){text-decoration:underline;text-decoration-color:#bd728f;text-decoration-thickness:2px;text-underline-offset:3px}.itn.itn-pastel .itn-sites dt{display:flex;align-items:center;flex-wrap:wrap;gap:0 .3em}.itn.itn-pastel img.itn-pen{display:inline-block;width:54px;height:54px;object-fit:contain;margin:0 6px 0 0;mix-blend-mode:multiply}.itn.itn-pastel .itn-wave{display:flow-root}.itn.itn-pastel img.itn-device{float:right;width:min(32%,240px);max-height:290px;object-fit:contain;margin:0 0 12px 24px}@media(max-width:600px){.itn.itn-pastel img.itn-device{display:block;float:none;width:min(65%,200px);margin:6px auto 16px}.itn.itn-pastel .itn-sites dt small{font-size:13px}}
.itn-wave-layout{display:grid;grid-template-columns:minmax(220px,32%) minmax(0,1fr);align-items:center;gap:clamp(20px,3vw,42px)}.itn.itn-pastel .itn-device-panel img.itn-device{display:block;float:none;width:100%;max-width:320px;max-height:none;height:auto;margin:0 auto}.itn-wavelengths>div{margin-top:16px;padding-top:14px;border-top:1px solid #d9c8d5}.itn.itn-pastel .itn-wavelengths h3{margin:0 0 5px;font-size:22px}.itn.itn-pastel .itn-wavelengths p,.itn.itn-pastel .itn-wave-note p{margin:4px 0;line-height:1.75}.itn-wave-note{margin-top:22px;padding:16px 20px;background:#f5edf3;border-radius:12px}.itn.itn-pastel .itn-wave-note h3{margin:0 0 6px}.itn-icon-wrap{display:inline-flex;position:relative;align-items:center;margin-right:5px}.itn.itn-pastel .itn-icon-wrap img.itn-pen{width:70px;height:70px;margin:0}.itn-twinkle{position:absolute;right:0;top:5%;font:19px/1 serif;color:#9e6685;pointer-events:none}@media(max-width:700px){.itn-wave-layout{grid-template-columns:minmax(0,1fr);gap:12px}.itn.itn-pastel .itn-device-panel img.itn-device{width:min(78%,265px)}.itn.itn-pastel .itn-icon-wrap img.itn-pen{width:66px;height:66px}}
.itn.itn-pastel #itn-price .itn-table table,.itn.itn-pastel #itn-price .itn-table :is(th,td){border:1px solid #ac92c2}.itn.itn-pastel #itn-price .itn-table thead th{background:#e7dcf1;color:#000}.itn.itn-pastel #itn-price .itn-table tbody th{background:#f6f0fa}.itn-wavelengths .itn-gem{font-size:.77em;vertical-align:.07em;margin-right:.45em}
.itn.itn-pastel .itn-wavelengths .itn-wave-title{display:flex;align-items:center;gap:.45em;font-size:clamp(16px,2vw,22px);line-height:1.45}.itn-wave-title span:nth-child(2){white-space:nowrap}.itn-diamond{display:inline-block;width:1.15em;height:1.1em;flex:none;background:center/contain no-repeat url("data:image/svg+xml,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20viewBox%3D'0%200%2032%2028'%3E%3Cg%20fill%3D'none'%20stroke%3D'%23754d69'%20stroke-width%3D'1.4'%20stroke-linecap%3D'round'%20stroke-linejoin%3D'round'%3E%3Cpath%20d%3D'M2%209L8%203l15%20.4%206%206L16%2025z%20M2%209l27%20.4%20M8%203l3.2%206.1L16%2025l5-15.8%202-5.8%20M11.2%209.1l4.6-5.7%205.2%205.8'%2F%3E%3C%2Fg%3E%3C%2Fsvg%3E")}.itn.itn-pastel .itn-saving{display:block;font:500 13px/1.5 sans-serif;color:#704365;margin-top:3px}.itn-price-site{display:inline-flex;align-items:center;gap:7px}.itn-price-site img{width:42px;height:42px;object-fit:contain;mix-blend-mode:multiply}.itn.itn-pastel #itn-price table{min-width:590px}.itn.itn-pastel #itn-price th,.itn.itn-pastel #itn-price td{vertical-align:middle}@media(max-width:450px){.itn.itn-pastel .itn-wavelengths .itn-wave-title{font-size:clamp(13px,3.65vw,16px);gap:.3em}}
.itn.itn-pastel #itn-faq details{overflow:hidden;margin:9px 0;border:1px solid #d7c4da;border-radius:13px;background:linear-gradient(115deg,rgba(255,255,255,.76),rgba(244,232,247,.44));box-shadow:inset 0 1px 0 #fff,0 3px 12px #8a648312;backdrop-filter:blur(8px)}.itn.itn-pastel #itn-faq details summary:not(:hover):not(:focus-visible){background:linear-gradient(115deg,rgba(255,255,255,.86),rgba(249,219,232,.55) 55%,rgba(231,220,248,.5));color:#000}.itn.itn-pastel #itn-faq details summary:is(:hover,:focus-visible){background:linear-gradient(110deg,#f8f1fb,#e6dced)}.itn.itn-pastel #itn-faq details[open] p{padding:10px 16px;margin:0}

